const v50Sha=b=>createHash('sha256').update(b).digest('hex');
const v50Tuple=p=>({path:p.path,bytes:p.bytes,sha256:p.sha256});
function v50SaveHexBytes(hex){assert.ok(typeof hex==='string'&&hex.length>0&&hex.length<=512*1024&&hex.length%2===0&&/^[0-9a-f]+$/i.test(hex),'Bounded even hexadecimal SAV payload');return Buffer.from(hex,'hex');}
function v50AssertPairBytes(a,b,label){for(const k of['sav0','sav1'])assert.ok(v50SaveHexBytes(a?.[k]).equals(v50SaveHexBytes(b?.[k])),label+' SAV bytes must match; hex letter case is not byte identity');}
function v50Path(p){assert.ok(typeof p==='string'&&p.length>0&&!p.startsWith('/')&&!p.includes('\\')&&!p.split('/').some(x=>!x||x==='.'||x==='..')&&!/^[a-z]:/i.test(p),'Bounded relative archive path');return p;}
function v50Pin(p){v50Path(p.path);assert.ok(Number.isSafeInteger(p.bytes)&&p.bytes>=0&&/^[0-9a-f]{64}$/.test(p.sha256));return v50Tuple(p);}
function v50Get(files,p,cap=32*1024*1024){v50Path(p);const b=files.get(p);assert.ok(Buffer.isBuffer(b),'Required original archive bytes: '+p);assert.ok(b.length<=cap,'One bounded archive input');return b;}
function v50Json(files,p,cap){return JSON.parse(v50Get(files,p,cap).toString('utf8'));}
function v50VerifyBytes(files,p,tuple,cap){const b=v50Get(files,p,cap);assert.deepEqual([b.length,v50Sha(b)],[tuple.bytes,tuple.sha256],'Original byte pin '+p);return b;}
function v50Budget(t){return{dailyRatio:t.meta.dailyRatio,monthlyRatio:t.meta.monthlyRatio,boutMax:t.meta.boutMax};}
function v50Map(t){const s=t.state,z=s.snapshot;return !s.menu.active&&!s.qty.active&&!s.record.active&&!z.fight.active&&!z.spe.active&&!z.result.active&&!z.top.active&&!z.report.active&&s.march.pick===1&&s.march.battlePick===0&&[0,7].includes(s.march.phase)&&s.overworld==='map';}
function v50PairInspection(a,b,anchor){const x=structuredClone(a),y=structuredClone(b);delete x.state.overworld;delete y.state.overworld;assert.deepEqual(y,x,'A/B full native fields except source-defined cached display must agree');if(anchor)assert.deepEqual(x,anchor,'No uncommanded change can be hidden by stabilization');const s=b.state,z=s.snapshot,expected=z.fight.active||z.spe.active||z.result.active||z.top.active||z.report.active||s.qty.active||s.record.active?'other':s.menu.active?(s.menu.context===1?'classic-menu':'other'):'map',ready=a.state.overworld===b.state.overworld&&(b.meta.overworldMode!=='hd-map'||b.state.overworld===expected);if(ready)assert.deepEqual(a,b,'The accepted A/B tickets are independently read and complete');return{anchor:x,ready,expected};}

function v50StripLedger(a,depth=0){assert.ok(a&&typeof a==='object'&&!Array.isArray(a)&&depth<=8);const {libBytes,...raw}=a;if(raw.resume)raw.resume={...raw.resume,history:v50StripLedger(raw.resume.history,depth+1)};return raw;}
function v50RuntimeLedger(a,libBytes,depth=0){assert.ok(depth<=8);assert.equal(Object.hasOwn(a,'libBytes'),false,'Persisted history contains original raw ledger fields, never a serialized runtime LIB Buffer');return{...a,libBytes,...(a.resume?{resume:{...a.resume,history:v50RuntimeLedger(a.resume.history,libBytes,depth+1)}}:{})};}
function v50ExactBirthTime(s){assert.equal(typeof s,'string');const m=/^(\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\d|3[01])T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d)\.([0-9]{1,7})Z$/.exec(s);assert.ok(m,'Exact UTC birth timestamp with one through seven fractional digits');return m[1]+'.'+m[2].padEnd(7,'0')+'Z';}
