 if(path===undefined||path===null)return null;assert.equal(path,'build/impact-skill-20261014/v50-post-exit-audit-v1.json','Only the root-declared supplemental post-exit record');const b=v50Get(files,path,128*1024),p=JSON.parse(b);assert.equal(p.accepted,true);assert.equal(p.originalCleanupTreeExited,cleanup.treeExited);assert.equal(cleanup.treeExited,false,'Supplemental evidence must retain the original unclosed lifecycle');v50VerifyBytes(files,p.originalResult.path,p.originalResult,1024*1024);assert.equal(p.originalResult.path,'build/impact-skill-20261014/city4-resume-actual-v50/result.json');assert.deepEqual(JSON.parse(files.get(p.originalResult.path)),result);
