 const servedBefore=json('served-source-before.json'),servedAfter=json('served-source-after.json'),served=servedBefore.sources.map(v50Pin);assert.equal(servedBefore.count,served.length);assert.equal(servedAfter.count,served.length);assert.deepEqual(servedAfter.sources.map(v50Pin),served);for(const p of served)assert.deepEqual(p,sourceMap.get(p.path),'Served bytes belong to the actual frozen whitelist');assert.equal(result.sourceVerification.servedCount,served.length);
