 assert.ok(Array.isArray(scenario.stableTickets)&&scenario.stableTickets.length<=256);let ordinal=0,lastObserved=0,fullPairCount=0;const ticketFilePins=new Map();for(const entry of scenario.stableTickets){assert.match(entry.file,/^stable-ticket-\d{3}\.json$/);const packet=JSON.parse(v50VerifyBytes(files,runDir+entry.file,entry,1024*1024));assert.equal(packet.label,entry.label);assert.equal(packet.pairs.length,entry.attempts);assert.equal(packet.timeout,entry.timeout);let anchor=null;for(const pair of packet.pairs){const current=[];for(const r of[pair.a,pair.b]){assert.equal(r.ordinal,ordinal++,'Each independent CDP read remains in actual ordinal order');assert.ok(Number.isFinite(r.startedAt)&&Number.isFinite(r.observedAt)&&r.startedAt>=lastObserved&&r.observedAt>=r.startedAt);lastObserved=r.observedAt;assert.equal(r.file,'native-ticket-'+r.sha256+'.json');const b=v50VerifyBytes(files,runDir+r.file,r,4*1024*1024),t=JSON.parse(b);assert.equal(b.toString('utf8'),JSON.stringify(t,null,2)+'\n','Complete canonical bytes, no implicit reconstruction');verifyCity4Ticket({ticket:t,libBytes,nativeBudget:v50Budget(t),observerExpected:false});assert.deepEqual([t.world.period,t.world.king,t.world.year,t.world.month],[4,0,239,10]);ticketFilePins.set(r.file,{path:r.file,bytes:r.bytes,sha256:r.sha256});current.push(t);}const v=v50PairInspection(current[0],current[1],anchor);anchor??=v.anchor;assert.equal(pair.ready,v.ready);assert.equal(pair.expected,v.expected);fullPairCount++;}if(!packet.timeout)assert.equal(packet.pairs.at(-1).ready,true);}assert.equal(scenario.actualTicketReads,ordinal);assert.equal(scenario.distinctTicketFiles,ticketFilePins.size);

