const V50_PREFIX='docs/validation/m5-wood-city4-resume-20261024-v50';
export function verifyV50Publication(root=process.cwd(),options={}){
 const readPublic=options.readPublic??(p=>v45ReadBounded(root,p)),readCurrent=options.readCurrent??(p=>{try{return v45ReadBounded(root,p);}catch(e){if(e.code==='ENOENT')return null;throw e;}});
 const C=JSON.parse(readPublic(V50_PREFIX+'.json'));assert.ok(Object.hasOwn(C,'observations'),'Complete canonical observations are mandatory');assert.equal(C.reader.path,V50_PREFIX+'-verify.mjs');assert.deepEqual(v45Pin(C.reader.path,readPublic(C.reader.path)),C.reader);assert.equal(C.readerDependency.path,'docs/validation/m5-quantity-ack-refresh-20261024-v45-verify.mjs');assert.deepEqual(v45Pin(C.readerDependency.path,readCurrent(C.readerDependency.path)),C.readerDependency);
 const index=JSON.parse(readPublic(C.archive.path)),decoded=decodeV45Archive({index,readPart:p=>readPublic(p)}),r=verifyV50Envelope({files:decoded.files,canonical:C,readPublic,readCurrent,verifyActual:verifyV50City4ResumeActual,readLatestOctoberInput,OCTOBER_INPUT_PINS,CITY4_HISTORY_INPUT_PINS});
 const pngs=[];for(const[p,b]of decoded.files)if(p.startsWith(C.runDir)&&p.endsWith('.png'))pngs.push({pin:v45Pin(p,b),decoded:decodeV45Png(b)});assert.deepEqual(pngs,C.pngs,'Every ordinary actual PNG is fully decoded');return{accepted:true,logicalFiles:decoded.logicalFiles,uniqueBlobs:decoded.physicalBlobs,ordinaryPngsDecoded:pngs.length,sourceBinding:r.sourceBinding,facts:r.facts,newBrowserRuns:0,newGameInputs:0,newDefaultTestExecutions:0,actualFlagsRewritten:false};
}
